async function syncMatchPollNotificationRows(env:Env){
 await env.DB.prepare("UPDATE match_polls SET status='open',updated_at=CURRENT_TIMESTAMP WHERE status='scheduled' AND julianday(opens_at)<=julianday('now') AND julianday(closes_at)>julianday('now') AND EXISTS(SELECT 1 FROM courts c WHERE c.id=match_polls.court_id AND c.status='open' AND c.moderation_status='visible' AND (c.opens_at IS NULL OR julianday(c.opens_at)<=julianday('now')))").run();
 await env.DB.prepare("UPDATE match_polls SET status='closed',updated_at=CURRENT_TIMESTAMP WHERE status IN ('scheduled','open') AND (julianday(closes_at)<=julianday('now') OR EXISTS(SELECT 1 FROM courts c WHERE c.id=match_polls.court_id AND c.status IN ('locked','settled','cancelled') OR EXISTS(SELECT 1 FROM fixtures f WHERE f.id=match_polls.fixture_id AND f.status='full_time')))").run();
 await env.DB.prepare("INSERT OR IGNORE INTO notifications(id,user_id,type,title,body,reference_id,event_key) SELECT lower(hex(randomblob(16))),cp.telegram_user_id,'match_poll_open','A Matchday poll is open',p.question,p.court_id,'match-poll-open:'||p.id||':'||cp.telegram_user_id FROM match_polls p JOIN court_participants cp ON cp.court_id=p.court_id AND cp.status='active' JOIN courts c ON c.id=p.court_id WHERE p.status='open' AND c.status='open' AND c.moderation_status='visible'").run();
}
async function telegramBotUsername(env:Env):Promise<string>{
 let username=env.TELEGRAM_BOT_USERNAME||"";
 if(!username&&env.TELEGRAM_BOT_TOKEN){
  try{const response=await fetch("https://api.telegram.org/bot"+env.TELEGRAM_BOT_TOKEN+"/getMe");const data=await response.json() as {ok?:boolean;result?:{username?:string}};if(data.ok&&data.result?.username)username=data.result.username;}catch{}
 }
 const normalized=username.replace(/^@/,"");return /^[A-Za-z0-9_]{5,32}$/.test(normalized)?normalized:"";
}


const SETHIS_MINI_APP_URL="https://settlethis.bk9ice.workers.dev/";
async function telegramBotCall(env:Env,method:string,payload:Record<string,unknown>){
 if(!env.TELEGRAM_BOT_TOKEN)throw new Error("Telegram bot token is not configured.");
 const response=await fetch("https://api.telegram.org/bot"+env.TELEGRAM_BOT_TOKEN+"/"+method,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});
 const data=await response.json() as {ok?:boolean;result?:unknown;description?:string};
 if(!response.ok||data.ok!==true)throw new Error(data.description||("Telegram "+method+" failed."));
 return data.result;
}
async function ensureTelegramBotSetup(env:Env){
 const username=await telegramBotUsername(env);
 if(!username)throw new Error("The Telegram bot username could not be resolved.");
 const saved=await env.DB.prepare("SELECT bot_username,webhook_configured_at FROM telegram_bot_settings WHERE id=1").first<{bot_username:string;webhook_configured_at:string|null}>();
 const fresh=!!saved?.webhook_configured_at&&(Date.now()-Date.parse(saved.webhook_configured_at+"Z"))<12*60*60*1000&&saved.bot_username===username;
 if(!fresh){
  const webhookSecret=(await sha256Hex(env.TELEGRAM_BOT_TOKEN+"|sethis-telegram-webhook-v1")).slice(0,32);
  const webhookUrl="https://settlethis.bk9ice.workers.dev/api/telegram/webhook";
  await telegramBotCall(env,"setWebhook",{url:webhookUrl,secret_token:webhookSecret,allowed_updates:["message"],drop_pending_updates:false});
  await telegramBotCall(env,"setChatMenuButton",{menu_button:{type:"web_app",text:"Play SETHIS",web_app:{url:SETHIS_MINI_APP_URL}}});
  await telegramBotCall(env,"setMyCommands",{commands:[{command:"start",description:"Start playing SETHIS football games"},{command:"help",description:"Get help with SETHIS"},{command:"stop",description:"Stop SETHIS broadcast messages"}]});
  await env.DB.prepare("INSERT INTO telegram_bot_settings(id,bot_username,webhook_configured_at,updated_at) VALUES(1,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(id) DO UPDATE SET bot_username=excluded.bot_username,webhook_configured_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP").bind(username).run();
 }else if(!saved?.bot_username){
  await env.DB.prepare("UPDATE telegram_bot_settings SET bot_username=?,updated_at=CURRENT_TIMESTAMP WHERE id=1").bind(username).run();
 }
 return {username,bot_url:"https://t.me/"+username+"?start=welcome",mini_app_url:SETHIS_MINI_APP_URL};
}
async function handleTelegramBotUpdate(request:Request,env:Env){
 if(!env.TELEGRAM_BOT_TOKEN)return json({error:"Telegram bot is not configured."},503);
 const expected=(await sha256Hex(env.TELEGRAM_BOT_TOKEN+"|sethis-telegram-webhook-v1")).slice(0,32);
 if(request.headers.get("x-telegram-bot-api-secret-token")!==expected)return json({error:"Webhook signature is invalid."},403);
 const update=await request.json() as {message?:{text?:string;chat?:{id?:number;type?:string};from?:{id?:number;is_bot?:boolean;username?:string;first_name?:string}}};
 const message=update.message,from=message?.from,chat=message?.chat;
 if(!message||!from?.id||!chat?.id||chat.type!=="private"||from.is_bot)return json({ok:true});
 const telegramId=String(from.id),textValue=String(message.text||"").trim();
 const command=textValue.match(/^\/(start|stop|help)(?:@[A-Za-z0-9_]+)?(?:\s+([A-Za-z0-9_-]{1,64}))?/i);
 const commandName=command?.[1]?.toLowerCase()||"";
 const payload=command?.[2]||"";
 if(commandName==="start"){
  await env.DB.prepare("INSERT INTO telegram_bot_members(telegram_user_id,username,first_name,broadcast_opt_in,pending_start_payload,start_payload,started_at,stopped_at,last_interaction_at,updated_at) VALUES(?,?,?,1,?,?,CURRENT_TIMESTAMP,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(telegram_user_id) DO UPDATE SET username=excluded.username,first_name=excluded.first_name,broadcast_opt_in=1,pending_start_payload=CASE WHEN excluded.pending_start_payload IS NOT NULL THEN excluded.pending_start_payload ELSE telegram_bot_members.pending_start_payload END,start_payload=CASE WHEN excluded.start_payload IS NOT NULL THEN excluded.start_payload ELSE telegram_bot_members.start_payload END,started_at=COALESCE(telegram_bot_members.started_at,CURRENT_TIMESTAMP),stopped_at=NULL,last_interaction_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP").bind(telegramId,from.username||null,from.first_name||"",payload||null,payload||null).run();
  const referred=payload.startsWith("ref_")?"Your friend's invite has been carried into your SETHIS registration.\n\n":"";
   const welcome="⚽ WELCOME TO SETHIS!\n\nThink you know football? Prove it.\nPlay Mystery Footballer and Football Runner, build your game record and earn eligible SETHIS rewards.\n\n🎯 START WITH MYSTERY FOOTBALLER\nChoose Easy, Medium or Hard and answer five multiple-choice football questions. Get all five right to earn the full difficulty reward.\n\nReady to play? Open the SETHIS Mini App and join the game. 👇";
  await telegramBotCall(env,"sendMessage",{chat_id:chat.id,text:welcome,reply_markup:{inline_keyboard:[[{text:"⚽ OPEN SETHIS & START PLAYING",web_app:{url:SETHIS_MINI_APP_URL}}]]}});
 }else if(commandName==="stop"){
  await env.DB.prepare("UPDATE telegram_bot_members SET broadcast_opt_in=0,stopped_at=CURRENT_TIMESTAMP,last_interaction_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE telegram_user_id=?").bind(telegramId).run();
  await telegramBotCall(env,"sendMessage",{chat_id:chat.id,text:"You have opted out of SETHIS broadcast messages. You can still open the Mini App and play. Send /start whenever you want to opt in again."});
 }else if(commandName==="help"){
  await env.DB.prepare("UPDATE telegram_bot_members SET last_interaction_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE telegram_user_id=?").bind(telegramId).run();
  await telegramBotCall(env,"sendMessage",{chat_id:chat.id,text:"SETHIS is home to football games and challenges. Start with Mystery Footballer: choose a difficulty and answer five multiple-choice football questions. You can also play Football Runner. Your game record and eligible rewards are saved to your registered account.",reply_markup:{inline_keyboard:[[{text:"⚽ OPEN SETHIS & PLAY",web_app:{url:SETHIS_MINI_APP_URL}}]]}});
 }else{
  await env.DB.prepare("UPDATE telegram_bot_members SET last_interaction_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE telegram_user_id=?").bind(telegramId).run().catch(()=>{});
 }
 return json({ok:true});
}



